  WHEN "categorie" = 'divertissement/livres/mangas' THEN 'autre'
  WHEN "categorie" = 'divertissement/livres/livres-jeunesse' THEN 'autre'
  WHEN "categorie" = 'divertissement/livres/livres-pratiques' THEN 'autre'
  WHEN "categorie" = 'divertissement/livres/beaux-livres' THEN 'autre'
  WHEN "categorie" = 'divertissement/livres/autres-livres' THEN 'autre'
  WHEN "categorie" = 'divertissement/musique/vinyles' THEN 'autre'
  WHEN "categorie" = 'divertissement/musique/cd' THEN 'autre'
  WHEN "categorie" = 'divertissement/musique/cassettes' THEN 'autre'
  WHEN "categorie" = 'divertissement/musique/instruments-de-musique' THEN 'loisirs-et-collections/instruments-de-musique-et-equipement/accessoires-pour-la-creation-musicale/autres-accessoires-musicaux'
  WHEN "categorie" = 'divertissement/films-et-series/dvd' THEN 'autre'
  WHEN "categorie" = 'divertissement/films-et-series/blu-ray' THEN 'autre'
  WHEN "categorie" = 'divertissement/films-et-series/vhs' THEN 'autre'
  WHEN "categorie" = 'divertissement/jeux-de-societe-et-puzzles/jeux-de-societe' THEN 'loisirs-et-collections/jeux-de-societe'
  WHEN "categorie" = 'divertissement/jeux-de-societe-et-puzzles/puzzles' THEN 'loisirs-et-collections/puzzles'
  WHEN "categorie" = 'divertissement/jeux-de-societe-et-puzzles/jeux-de-cartes' THEN 'loisirs-et-collections/cartes-a-collectionner/jeux-de-cartes'
  WHEN "categorie" = 'divertissement/collections/pin-s' THEN 'loisirs-et-collections/souvenirs/autres-souvenirs'
  WHEN "categorie" = 'divertissement/collections/cartes-a-collectionner' THEN 'loisirs-et-collections/cartes-a-collectionner/cartes-a-collectionner-a-l-unite'
  WHEN "categorie" = 'divertissement/collections/figurines-de-collection' THEN 'loisirs-et-collections/souvenirs/autres-souvenirs'
  WHEN "categorie" = 'divertissement/collections/pieces-et-billets' THEN 'loisirs-et-collections/pieces-de-monnaie-et-billets/pieces-de-monnaie'
  WHEN "categorie" = 'divertissement/collections/timbres' THEN 'loisirs-et-collections/timbres/timbres-a-l-unite'
  WHEN "categorie" = 'divertissement/collections/autres-objets-de-collection' THEN 'loisirs-et-collections/souvenirs/autres-souvenirs'
  WHEN "categorie" = 'divertissement/loisirs-creatifs' THEN 'loisirs-et-collections/loisirs-creatifs/fournitures-pour-loisirs-creatifs/autocollants'
  WHEN "categorie" = 'sport/football' THEN 'sport/sports-d-equipe/football/autres-accessoires-de-football'
  WHEN "categorie" = 'sport/rugby' THEN 'sport/sports-d-equipe/rugby/autres-equipements-de-rugby'
  WHEN "categorie" = 'sport/basketball' THEN 'sport/sports-d-equipe/basketball/autres-accessoires-de-basket'
  WHEN "categorie" = 'sport/sports-de-raquette' THEN 'sport/sports-de-raquette/tennis/autres-accessoires-de-tennis'
  WHEN "categorie" = 'sport/velos-et-accessoires' THEN 'sport/cyclisme/accessoires-et-outils-pour-velo/autres-accessoires-pour-velo'
  WHEN "categorie" = 'sport/fitness-et-musculation' THEN 'sport/fitness-course-a-pied-et-yoga/accessoires-de-fitness-a-domicile/autres-accessoires-de-fitness'
  WHEN "categorie" = 'sport/running' THEN 'sport/fitness-course-a-pied-et-yoga/course-a-pied/autres-accessoires-pour-course-a-pied'
  WHEN "categorie" = 'sport/randonnee-et-camping' THEN 'sport/sports-de-plein-air/autres-accessoires-de-sports-de-plein-air'
  WHEN "categorie" = 'sport/sports-d-hiver' THEN 'sport/sports-d-hiver/materiel-de-ski/autres-equipements-de-ski'
  WHEN "categorie" = 'sport/sports-nautiques' THEN 'sport/sports-nautiques/accessoires-pour-sports-nautiques/autres-accessoires-pour-sports-nautiques'
  WHEN "categorie" = 'sport/peche-et-chasse' THEN 'sport/sports-de-plein-air/peche-et-chasse/autres-accessoires-de-peche-et-de-chasse'
  WHEN "categorie" = 'sport/sports-de-combat' THEN 'sport/boxe-et-arts-martiaux/autres-equipements-pour-arts-martiaux'
  WHEN "categorie" = 'sport/equitation' THEN 'sport/equitation/selles-et-harnachement/autres-equipements-d-harnachement'
  WHEN "categorie" = 'sport/golf' THEN 'sport/golf/accessoires-de-golf'
  WHEN "categorie" = 'sport/equipement-moto' THEN 'autre'
  WHEN "categorie" = 'sport/autres-sports' THEN 'sport/sports-et-jeux-de-loisir/balles-et-ballons'
  WHEN "categorie" LIKE 'enfants/%' THEN 'autre'
  WHEN "categorie" LIKE 'maison/%' THEN 'autre'
  WHEN "categorie" LIKE 'electronique/%' THEN 'autre'
  WHEN "categorie" LIKE 'animaux/%' THEN 'autre'
  WHEN "categorie" LIKE 'divertissement/%' THEN 'autre'
  ELSE "categorie"
END
WHERE "categorie" IS NOT NULL;
